// Turn a submitted requisition into a ClickUp task body.
//
// The app sends labels, never option UUIDs, so this is where labels become
// UUIDs against the live field list. It also decides three things before
// anything is created: is this submissionId one we have already accepted, is
// there an open requisition that looks like this one, and does the workspace
// actually carry every field this payload needs.

const NAME_TO_KEY = {
  'company': 'company',
  'department': 'department',
  'cost centre': 'costCentre',
  'cost center': 'costCentre',
  'section': 'section',
  'work location': 'location',
  'location': 'location',
  'job grade': 'jobGrade',
  'job code no': 'jobCodeNo',
  'job code': 'jobCodeNo',
  'position type': 'positionType',
  'position new replacement': 'newOrReplacement',
  'total sub positions': 'totalSubPositions',
  'recruitment type': 'recruitmentType',
  'requesting manager': 'requestingManager',
  'reporting to': 'reportingTo',
  'others reporting indirectly': 'othersReportingIndirectly',
  'job overview': 'jobOverview',
  'key responsibilities outcomes': 'keyResponsibilitiesOutcomes',
  'key responsibilities and outcomes': 'keyResponsibilitiesOutcomes',
  'educational qualification': 'educationalQualification',
  'relevant skills experience attributes': 'relevantSkillsExperienceAttributes',
  'relevant skills experience and attributes': 'relevantSkillsExperienceAttributes',
  'previous failures successes': 'previousFailuresSuccesses',
  'competitive advantage': 'competitiveAdvantage',
  '6 months objectives': 'sixMonthsObjectives',
  'potential career path': 'potentialCareerPath',
  'position requirements': 'positionRequirements',
  'assessment stages required': 'assessmentStagesRequired',
  'interview panel': 'interviewPanel',
  'requisition raised': 'requisitionRaised',
};

const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// ---- contract guard, v1.0 ------------------------------------------------
// The wire contract is docs/requisition-submission-1.0.schema.json. Validate
// the body against it in a JSON Schema node ahead of this one and return the
// 422 shape from §8; what follows assumes a body that already passed.
// 1.1 loosened section, jobGrade and jobCodeNo to nullable when the form
// stopped asking for them. 1.0 is still accepted for a stale tab.
const SUPPORTED_SCHEMA_VERSIONS = ['1.0', '1.1'];

const incoming = $('Webhook').first().json.body || {};
if (!SUPPORTED_SCHEMA_VERSIONS.includes(incoming.schemaVersion)) {
  // n8n must never mis-map a future version into the v1.0 branch
  throw new Error(`Unsupported schemaVersion "${incoming.schemaVersion}"`);
}

const body = incoming;
const submissionId = body.submissionId;
if (!submissionId) {
  throw new Error('submissionId is required — refusing a submission that cannot be deduplicated');
}

const position = body.position || {};
const reporting = body.reporting || {};
const jd = body.jobDescription || {};
const businessCase = body.businessCase || {};
const provisioning = body.provisioning || {};
const hiring = body.hiringProcess || {};

// The marker that makes this endpoint idempotent. ClickUp has no natural
// place for an external key, so it rides in the description and is matched
// against tasks already on the list.
const MARKER = `<!-- submissionId:${submissionId} -->`;

const existing = $('ClickUp - Open Requisitions').first().json.tasks || [];

const duplicate = existing.find((task) =>
  (task.description || '').includes(MARKER) || (task.text_content || '').includes(MARKER));
if (duplicate) {
  return [{ json: { action: 'duplicate', taskId: duplicate.id, taskUrl: duplicate.url } }];
}

// A-6 · the same title in the same company and department, still open. The
// manager decides whether that is a collision; we only report it.
const advisories = [];
const acknowledged = body.advisoriesAcknowledged || [];
if (!acknowledged.includes('A-6')) {
  const fieldValue = (task, name) => {
    const field = (task.custom_fields || []).find((f) => norm(f.name) === norm(name));
    if (!field) return undefined;
    const options = field.type_config?.options || [];
    const option = options.find((o) => o.id === field.value || o.orderindex === field.value);
    return option ? (option.name ?? option.label) : field.value;
  };

  const similar = existing.find((task) =>
    norm(task.name) === norm(position.jobTitle) &&
    fieldValue(task, 'Company') === position.company &&
    fieldValue(task, 'Department') === position.department);

  if (similar) {
    // v1.0 §8: A-6 travels with the 201 rather than blocking the submission.
    // The requisition is filed, and the manager is told what HR will also see.
    advisories.push({
      code: 'A-6',
      message: 'A similar requisition is already open.',
      taskUrl: similar.url,
    });
  }
}

// ---- resolve labels to option UUIDs ------------------------------------
const fields = {};
for (const field of ($('ClickUp - List Fields').first().json.fields || [])) {
  const key = NAME_TO_KEY[norm(field.name)];
  if (key) fields[key] = field;
}

const optionId = (key, label) => {
  const options = fields[key]?.type_config?.options || [];
  const match = options.find((o) => (o.name ?? o.label) === label);
  if (!match) {
    throw new Error(`"${label}" is not an option on ${fields[key]?.name || key} — the form and the workspace disagree`);
  }
  return match.id;
};

const custom = [];
const put = (key, value) => {
  if (value === null || value === undefined || value === '') return;
  if (!fields[key]) {
    // Refusing loudly beats writing a requisition that is missing an answer
    throw new Error(`The Positions list has no field for "${key}" — create it before accepting requisitions`);
  }
  custom.push({ id: fields[key].id, value });
};

const putChoice = (key, label) => { if (label) put(key, optionId(key, label)); };
const putLabels = (key, labels) => {
  if (Array.isArray(labels) && labels.length) put(key, labels.map((l) => optionId(key, l)));
};

putChoice('company', position.company);
putChoice('department', position.department);
putChoice('costCentre', position.costCentre);
putChoice('location', position.location);
putChoice('positionType', position.positionType);
putChoice('newOrReplacement', position.newOrReplacement);
putLabels('recruitmentType', position.recruitmentType);
put('section', position.section);
put('jobGrade', position.jobGrade);
put('jobCodeNo', position.jobCodeNo);
put('totalSubPositions', Number(position.totalSubPositions));

if (reporting.requestingManager?.clickupUserId) {
  put('requestingManager', { add: [reporting.requestingManager.clickupUserId], rem: [] });
}
put('reportingTo', reporting.reportingTo);
put('othersReportingIndirectly', reporting.othersReportingIndirectly);

put('jobOverview', jd.jobOverview);
const escapeCell = (s) => String(s).replace(/\s*\r?\n\s*/g, ' ').trim().replace(/\|/g, '\\|');
const rederived = [
  '| Key responsibility | Outcome – indicator of success |',
  '|---|---|',
  ...(jd.keyResponsibilitiesRows || []).map(
    (r) => `| ${escapeCell(r.responsibility)} | ${escapeCell(r.outcome)} |`),
].join('\n');
if (rederived !== jd.keyResponsibilitiesMarkdown) {
  throw new Error('keyResponsibilitiesMarkdown does not match the rows it claims to describe');
}
put('keyResponsibilitiesOutcomes', rederived);
put('educationalQualification', jd.educationalQualification);
put('relevantSkillsExperienceAttributes', jd.relevantSkillsExperienceAttributes);

put('previousFailuresSuccesses', businessCase.previousFailuresSuccesses);
put('competitiveAdvantage', businessCase.competitiveAdvantage);
put('sixMonthsObjectives', businessCase.sixMonthsObjectives);
put('potentialCareerPath', businessCase.potentialCareerPath);

putLabels('positionRequirements', provisioning.positionRequirements);
putLabels('assessmentStagesRequired', hiring.assessmentStagesRequired);

const panel = (hiring.interviewPanel || []).map((p) => p.clickupUserId).filter(Boolean);
if (panel.length) put('interviewPanel', { add: panel, rem: [] });

put('requisitionRaised', new Date(body.submittedAt || Date.now()).getTime());

// Agency name and who-is-being-replaced have no field of their own yet, so
// they travel in the description where HR can still read them.
const notes = [MARKER];
if (position.agencyName) notes.push(`Recruitment agency: ${position.agencyName}`);
if (position.replacingEmployee?.displayName) {
  notes.push(`Replacing: ${position.replacingEmployee.displayName}`);
}
if (body.advisoriesAcknowledged?.length) {
  notes.push(`Advisories acknowledged: ${body.advisoriesAcknowledged.join(', ')}`);
}

return [{
  json: {
    action: 'create',
    advisories,
    task: {
      name: position.jobTitle,
      description: notes.join('\n'),
      status: 'Draft',
      tags: ['requisition'],
      custom_fields: custom,
    },
  },
}];

// The §8 success body. `duplicate: true` is the idempotent replay, and the app
// treats it as the success it is — never an error.
const created = $input.first().json;
const decision = $('Build Task').first().json;
const body = $('Webhook').first().json.body || {};

return [{
  json: {
    ok: true,
    submissionId: body.submissionId,
    taskId: created.id,
    taskUrl: created.url,
    // TODO(kenafric): `reference` is the human-readable REQ-YYYY-NNNN. Generate
    // it here once the numbering scheme is agreed; the app falls back to the
    // task id until it exists.
    reference: null,
    duplicate: decision.action === 'duplicate',
    advisories: decision.advisories || [],
  },
}];

// Nothing was created because we have already accepted this submissionId.
// That is still a success: the app shows the original receipt.
const decision = $input.first().json;
const body = $('Webhook').first().json.body || {};

return [{
  json: {
    ok: true,
    submissionId: body.submissionId,
    taskId: decision.taskId,
    taskUrl: decision.taskUrl,
    reference: null,
    duplicate: true,
    advisories: decision.advisories || [],
  },
}];
